  "summary": "The code contained a critical Remote Code Execution vulnerability due to the use of eval(), alongside several maintainability issues including missing documentation and magic numbers. The refactored code replaces eval() with a safe mathematical evaluation approach and introduces constants and type hints for better code quality.",
  "fixed_code": "from flask import Flask, jsonify, request\nimport ast\nimport operator\n\napp = Flask(__name__)\n\nMAX_EXPR_LENGTH = 200\n\ndef safe_eval(node):\n    operators = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv, ast.USub: operator.neg}\n    if isinstance(node, ast.Constant): return node.value\n    if isinstance(node, ast.BinOp): return operators[type(node.op)](safe_eval(node.left), safe_eval(node.right))\n    if isinstance(node, ast.UnaryOp): return operators[type(node.op)](safe_eval(node.operand))\n    raise ValueError(\"Unsupported expression\")\n\n@app.route(\"/calc\")\ndef calc() -> flask.Response:\n    \"\"\"Calculates the result of a mathematical expression provided via query parameter 'expr'.\"\"\"\n    expr = request.args.get(\"expr\", \"0\")\n    if len(expr) > MAX_EXPR_LENGTH:\n        return jsonify(error=\"expression too long\"), 400\n    try:\n        result = safe_eval(ast.parse(expr, mode='eval').body)\n        return jsonify(result=result)\n    except Exception:\n        return jsonify(error=\"Invalid expression\"), 400"
